#!/usr/bin/env node
/**
 * Builds the LYNK UI bundles from the single source of truth in `lynk/`.
 *
 *   mobile : ui.js -> shared/engine.js -> shared/map.js -> boot.js
 *   desktop: ui.js -> shared/engine.js -> shared/map.js -> init.js
 *
 * The prototype code relies on globals (UI, A, S, $ ...), so each variant is
 * concatenated into ONE plain classic script (no IIFE, no modules).
 *
 * Outputs (all git-ignored, regenerated by `predev` / `prebuild`):
 *   public/lynk/<variant>.<hash>.js
 *   lynk/generated/manifest.json          { mobile: "mobile.<hash>.js", desktop: ... }
 *   lynk/generated/<variant>.css.ts       default export: the variant CSS
 *   lynk/generated/<variant>.html.ts      default export: the variant body markup
 */
import { createHash } from "node:crypto";
import { mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const src = (p) => readFileSync(join(root, "lynk", p), "utf8");

const VARIANTS = {
  mobile: {
    js: ["mobile/ui.js", "shared/engine.js", "shared/map.js", "mobile/boot.js"],
    css: ["mobile/styles.css", "mobile/native.css"],
    html: "mobile/body.html",
  },
  desktop: {
    js: ["desktop/ui.js", "shared/engine.js", "shared/map.js", "desktop/init.js"],
    css: ["desktop/styles.css", "desktop/native.css"],
    html: "desktop/body.html",
  },
};

const outJs = join(root, "public", "lynk");
const outGen = join(root, "lynk", "generated");
rmSync(outJs, { recursive: true, force: true });
rmSync(outGen, { recursive: true, force: true });
mkdirSync(outJs, { recursive: true });
mkdirSync(outGen, { recursive: true });

const banner = "// GENERATED by scripts/build-lynk.mjs from lynk/ - do not edit.\n";
const manifest = {};

for (const [name, v] of Object.entries(VARIANTS)) {
  const js =
    `/* LYNK ${name} - generated from lynk/ by scripts/build-lynk.mjs */\n` +
    v.js.map((f) => `/* ---- ${f} ---- */\n${src(f)}\n;`).join("\n");
  const hash = createHash("sha256").update(js).digest("hex").slice(0, 10);
  const file = `${name}.${hash}.js`;
  writeFileSync(join(outJs, file), js);
  manifest[name] = file;

  const css = v.css.map((f) => src(f)).join("\n");
  writeFileSync(join(outGen, `${name}.css.ts`), `${banner}const css: string = ${JSON.stringify(css)};\nexport default css;\n`);
  writeFileSync(join(outGen, `${name}.html.ts`), `${banner}const html: string = ${JSON.stringify(src(v.html))};\nexport default html;\n`);
  console.log(`[build-lynk] ${name}: /lynk/${file} (${(js.length / 1024).toFixed(1)} KB js, ${(css.length / 1024).toFixed(1)} KB css)`);
}

writeFileSync(join(outGen, "manifest.json"), JSON.stringify(manifest, null, 2) + "\n");
